H.background();
const w = H.W;
const beta = Math.min(0.99, Math.max(0, P.beta));
const gamma = 1 / Math.sqrt(Math.max(1e-6, 1 - beta * beta));
const L0 = Math.max(0.5, P.L0);
const L = L0 / gamma;
const v = H.plot2d({ xMin: 0, xMax: 12, yMin: -1, yMax: 6 });
v.grid(); v.axes();
// Rest-frame rocket (proper length L0) shown faint at top as the reference.
const restY = 4.2, hRk = 0.7;
v.rect(1, restY, L0, hRk, { fill: H.hsl(210, 50, 35, 0.5), stroke: H.colors.sub, width: 1.5 });
v.text("proper length  L0 = " + L0.toFixed(1) + " m", 1, restY + hRk + 0.5, { color: H.colors.sub, size: 12 });
// Moving (contracted) rocket loops across the window.
const nose = (t * (0.8 + beta * 2.2)) % (12 + L) - L;
const tail = nose - L;
const movY = 1.3;
v.rect(tail, movY, L, hRk, { fill: H.colors.accent2, stroke: H.colors.ink, width: 1.5 });
v.line(tail, movY - 0.3, nose, movY - 0.3, { color: H.colors.warn, width: 2 });
v.arrow(nose - L * 0.5, movY + hRk + 0.6, nose - L * 0.5 + 0.4 + beta * 1.8, movY + hRk + 0.6, { color: H.colors.warn, width: 2.5 });
H.text("Length contraction: L = L0 / γ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("β = v/c = " + beta.toFixed(2) + "    γ = " + gamma.toFixed(3), 24, 52, { color: H.colors.sub, size: 13 });
H.text("L0 = " + L0.toFixed(1) + " m   →   contracted L = " + L.toFixed(2) + " m", 24, 74, { color: H.colors.good, size: 13 });
H.legend([{ label: "rest length L0", color: H.colors.sub }, { label: "moving (contracted) L", color: H.colors.accent2 }], w - 230, 28);
